import base64,hashlib,io,json,os,subprocess,sys,tarfile
from pathlib import Path
os.environ['SOL_SOURCE_REVISION']='27d35879d0eea5d49da93895f54bd458bdaf16de'
root=Path('/kaggle/working/code');root.mkdir(parents=True,exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode('')),mode='r:gz') as tar:tar.extractall(root)
manifest={'shared/__init__.py': 'a5d8360a9c1a06dc42b0b1c336e0cfaa7e7edd4605ee67daf1049bc0798edb36', 'shared/data_split.py': 'f534c584da409642b0462d48c5c88f1658e6ce9f310b22996ca4461369ce780e', 'shared/utils.py': '97c2ffb5c4b0b870775769988295533ddf5142499080f41df4fe31b2b6e17a44', 'experiments/exp_033_inference/__init__.py': 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', 'experiments/exp_033_inference/src/__init__.py': 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', 'experiments/exp_033_inference/src/sweep.py': '9923412adb27609fe2d70a51e7baa80559addf99ca85999c65cd8fc062b6c01b', 'scripts/audit_cross_architecture_verifier.py': '654e5fe27a19b31ef936570461d5e0f1e113e21ff864eacdbd45b7b700e03ce8'}
for name,digest in manifest.items():assert hashlib.sha256((root/name).read_bytes()).hexdigest()==digest,name
(root/'scripts'/'__init__.py').touch()
os.environ['PYTHONPATH']=str(root)
subprocess.check_call([sys.executable,'-m','pip','install','-q','pycocotools'])
source=Path('/kaggle/input')
annotations=next(source.rglob('MAGFiLO_1.0_Annotations_kaggle2026_train.json'))
assert hashlib.sha256(annotations.read_bytes()).hexdigest()=='5da9e92b5a1a1947fd5d57adb6688269625c48ec1ef884daf2a01618c9ed54a1'
pools=[p.parent for p in source.rglob('manifest.json') if 'sol-exp002-pools' in str(p)]
assert len(pools)==1,[str(p) for p in pools]
declared=json.loads((pools[0]/'manifest.json').read_text())
for name,facts in declared.items():
    got=hashlib.sha256((pools[0]/name).read_bytes()).hexdigest()
    assert got==facts['sha256'],(name,got,facts['sha256'])
print('EXP002_POOLS',sorted(declared),flush=True)
partner=[p for p in source.rglob('d4_pool_stage2_best.json')]
assert partner,'exp098 validation pool not attached; kernel_sources missing'
print('EXP097_POOL',[str(p) for p in partner],flush=True)
subprocess.run([sys.executable,'-u','-m','scripts.audit_cross_architecture_verifier',
 '--exp002-pool',str(pools[0]/'exp002_val_pool.json'),
 '--exp097-pool',str(partner[0]),
 '--annotations',str(annotations),
 '--output','/kaggle/working']+['--floor', '0.1', '--grow', '-1', '--min-area', '300'],cwd=root,check=True,timeout=30000)
print('KERNEL_COMPLETE',flush=True)
